html:
{#
  CRM Contract Standard — Tiberbu CareVerse
  DocType: CRM Contract
  Children: doc.signatories (CRM Contract Signatory)
#}

<div class="page-break ct-wrap">

<style>
  /* ── Reset ── */
  .ct-wrap { font-family: "Inter", Arial, sans-serif; color: #1a1a1a; font-size: 12px; line-height: 1.5; }
  .ct-wrap * { box-sizing: border-box; }

  /* ── Header band ── */
  .ct-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 18px; }
  .ct-company-name { font-size: 20px; font-weight: 800; color: #1e3a5f; letter-spacing: -0.01em; }
  .ct-company-sub { font-size: 10px; color: #64748b; margin-top: 2px; }
  .ct-doc-meta { text-align: right; }
  .ct-doc-title { font-size: 22px; font-weight: 800; color: #1e3a5f; letter-spacing: 0.06em; text-transform: uppercase; }
  .ct-doc-ref { font-size: 11px; color: #374151; margin-top: 4px; }
  .ct-doc-ref span { font-weight: 600; }

  /* ── Divider ── */
  .ct-rule { border: none; border-top: 2px solid #1e3a5f; margin: 10px 0; }
  .ct-rule-thin { border: none; border-top: 1px solid #e2e8f0; margin: 6px 0; }

  /* ── Status badge ── */
  .ct-status-badge { display: inline-block; padding: 2px 8px; border-radius: 8px; font-size: 10px; font-weight: 700; }

  /* ── Contract body ── */
  .ct-body { margin: 16px 0; font-size: 11.5px; color: #1a1a1a; line-height: 1.7; }
  .ct-body p { margin-bottom: 8px; }
  .ct-body h1, .ct-body h2, .ct-body h3 { color: #1e3a5f; margin-top: 14px; margin-bottom: 6px; }
  .ct-body table { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
  .ct-body table td, .ct-body table th { border: 1px solid #e2e8f0; padding: 5px 8px; font-size: 11px; }
  .ct-body table th { background: #1e3a5f; color: #fff; font-weight: 600; }

  /* ── Section title ── */
  .ct-section-title {
    font-size: 10px; font-weight: 700; color: #1e3a5f;
    text-transform: uppercase; letter-spacing: 0.07em;
    margin-top: 20px; margin-bottom: 8px;
    border-bottom: 2px solid #1e3a5f; padding-bottom: 4px;
  }

  /* ── Signature grid ── */
  .ct-sig-grid { display: flex; flex-wrap: wrap; gap: 16px; margin-top: 8px; }
  .ct-sig-card {
    flex: 0 0 calc(33.33% - 12px);
    border: 1px solid #e2e8f0; border-radius: 6px;
    padding: 14px; background: #f8fafc;
  }
  .ct-sig-party { font-size: 11px; font-weight: 700; color: #1e3a5f; margin-bottom: 2px; }
  .ct-sig-role-label { font-size: 10px; color: #64748b; margin-bottom: 10px; }
  .ct-sig-img-wrap {
    min-height: 80px; display: flex; align-items: center; justify-content: center;
    margin-bottom: 8px; border-bottom: 1px solid #334155; padding-bottom: 8px;
  }
  .ct-sig-img-wrap img { max-height: 80px; max-width: 100%; }
  .ct-sig-line-label { font-size: 9px; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.06em; padding-top: 4px; }
  .ct-sig-date { font-size: 10px; color: #374151; margin-top: 6px; }
  .ct-sig-date span { font-weight: 600; }

  /* ── Footer ── */
  .ct-footer {
    margin-top: 24px; padding: 10px 14px;
    background: #f0f4ff; border-left: 4px solid #1e3a5f;
    font-size: 10px; color: #374151; font-style: italic;
  }
</style>

{# ── HEADER ── #}
<div class="ct-header">
  <div>
    <div class="ct-company-name">TIBERBU</div>
    <div class="ct-company-sub">Tiberbu Healthnet Solutions Limited</div>
    <div class="ct-company-sub">18th Floor, 4th Avenue Tower, Ngong Road, Nairobi</div>
    <div class="ct-company-sub">P.O. Box 17587-00100 Nairobi, Kenya</div>
    <div class="ct-company-sub">legal@tiberbu.com  |  +254 709 208 000</div>
  </div>
  <div class="ct-doc-meta">
    <div class="ct-doc-title">SERVICE AGREEMENT</div>
    <div class="ct-doc-ref">Contract Ref.: <span>{{ doc.name }}</span></div>
    <div class="ct-doc-ref">Contract Date: <span>{{ frappe.utils.format_date(doc.contract_date) if doc.contract_date else "—" }}</span></div>
    {% if doc.deal %}
    <div class="ct-doc-ref">Deal: <span>{{ doc.deal }}</span></div>
    {% endif %}
    <div class="ct-doc-ref" style="margin-top:6px;">
      Status:
      <span class="ct-status-badge" style="
        {% if doc.status == 'Fully Executed' %}background:#dcfce7;color:#166534;
        {% elif doc.status == 'Cancelled' %}background:#fee2e2;color:#991b1b;
        {% elif doc.status == 'Awaiting Signatures' %}background:#dbeafe;color:#1e40af;
        {% else %}background:#f1f5f9;color:#475569;{% endif %}">
        {{ doc.status }}
      </span>
    </div>
  </div>
</div>

<hr class="ct-rule">

{# ── CONTRACT BODY ── #}
{% if doc.contract_html %}
<div class="ct-body">
  {{ doc.contract_html | safe }}
</div>
{% endif %}

<hr class="ct-rule-thin" style="margin-top:20px;">

{# ── SIGNATURES ── #}
<div class="ct-section-title">Authorised Signatures</div>
<div class="ct-sig-grid">
{% for row in doc.signatories %}
  {% if row.status == "Signed" and row.signature_data %}
  <div class="ct-sig-card">
    <div class="ct-sig-party">For: {{ row.signatory_name }}</div>
    <div class="ct-sig-role-label">Role: {{ row.signatory_role }}{% if row.is_witness %} &mdash; Witness{% if row.witnessing_for %} for {{ row.witnessing_for }}{% endif %}{% endif %}</div>
    <div class="ct-sig-img-wrap">
      <img src="{{ row.signature_data }}" alt="Signature" style="max-height:80px;">
    </div>
    <div class="ct-sig-line-label">Signature</div>
    {% if row.signed_at %}
    <div class="ct-sig-date">Date: <span>{{ frappe.utils.format_datetime(row.signed_at) }}</span></div>
    {% endif %}
  </div>
  {% endif %}
{% endfor %}
</div>

{# ── FOOTER ── #}
<div class="ct-footer">
  This agreement was digitally executed via the CareverseHIMS opt-in portal. Signatures were captured with email OTP verification.
</div>

</div>{# end page-break #}
